 function columns(source=sheet(),r=ref){const b=bounds(r);return Object.fromEntries(Array.from({length:b.width},(_,i)=>[i,String.fromCharCode(65+b.c0+i)+' · '+String(value(source,address(b.r0,b.c0+i))||'Columna '+(i+1))]));}
