 function openFilter(sourceRef=region(),column){mode='filter';ref=sourceRef;const b=bounds(ref),col=column??b.c0,old=(sheet().filters||[]).find(f=>f.range===ref&&f.column===col),vals=[...new Set(dataMatrix(sheet(),ref).slice(1).map(r=>String(r[col-b.c0])))].sort((a,b)=>a.localeCompare(b,'es',{numeric:true})),cols=Object.fromEntries(Object.entries(columns()).map(([i,label])=>[b.c0+Number(i),label]));show('Filtro por columna',field('range','Rango con encabezados',ref,'text','data-filter-range')+choice('filter-column','Columna',cols,col,'data-filter-column')+choice('filter-op','Condición',opItems,old?.op||'contains','data-filter-op')+field('filter-query','Valor',old?.query||'','text','data-column-query data-filter-text')+field('filter-second','Segundo límite',old?.second||'')+'<details><summary>Seleccionar valores</summary>'+check('filter-all','Seleccionar todo',true)+vals.map((v,i)=>'<label class="sx-data-check"><input data-dt-filter-value type="checkbox" value="'+esc(v)+'" '+(!old?.values||old.values.includes(v)?'checked':'')+'> '+esc(v||'(Vacías)')+'</label>').join('')+'</details>'+btn('apply-column-filter','Aplicar filtro')+btn('data-filter-enable','Activar / quitar flechas')+btn('unfilter','Borrar filtros'));updateFilter();}
