 function updateValidation(){const type=get('validation-type'),op=get('validation-op');const allowed={ 'validation-op':!['any','list','custom'].includes(type),'validation-a':!['any','list','custom'].includes(type),'validation-b':!['any','list','custom'].includes(type)&&['between','notbetween'].includes(op),'validation-list':type==='list','validation-formula':type==='custom','in-cell':type==='list'};for(const [id,visible] of Object.entries(allowed)){const n=dialog.querySelector('[data-dt="'+id+'"]');if(n)n.closest('label').hidden=!visible;}for(const id of ['validation-a','validation-b']){const n=dialog.querySelector('[data-dt="'+id+'"]');if(n)n.placeholder=type==='date'?'AAAA-MM-DD o fórmula':type==='time'?'HH:MM:SS o fórmula':'';}}
