 function importPanel(){mode='import';const d=importDraft;show('Importar y transformar',field('query-name','Nombre de consulta',d.name||'Importación')+choice('import-kind','Formato',{csv:'Texto / CSV',json:'JSON',xml:'XML de registros'},d.kind||'csv')+'<label>Contenido<textarea data-dt="import-text" rows="5">'+esc(d.text||'')+'</textarea></label>'+choice('separator','Delimitador',{';':'Punto y coma',',':'Coma','\t':'Tabulación','|':'Barra vertical'},d.separator||';','data-csv-separator')+choice('encoding','Codificación',{utf8:'UTF-8',windows:'Windows-1252'},d.encoding||'utf8')+check('header','Primera fila con encabezados',true)+choice('import-type','Tipo de las columnas',types,'general')+'<p>Se carga en una nueva hoja. Los textos que comienzan por = se conservan como texto.</p>'+btn('data-preview-import','Vista previa')+btn('apply-csv','Cargar como consulta')+'<div data-dt-output></div>');}
 function parseImportPayload(text,kind,separator=';',header=true,columnTypes=[]){
  if(kind==='xml'){if(text.length>2e6)throw Error('El contenido supera 2 MB.');const doc=new DOMParser().parseFromString(text,'application/xml');if(doc.querySelector('parsererror')||/<!DOCTYPE|<!ENTITY/i.test(text))throw Error('XML no válido o con entidades no admitidas.');const records=[...doc.documentElement.children];if(!records.length)throw Error('El XML debe tener registros como hijos de la raíz.');const fields=[...new Set(records.flatMap(r=>[...r.children].map(n=>n.tagName)))];if(records.some(r=>[...r.children].some(n=>n.children.length)))throw Error('Usa registros XML planos.');const rows=[fields,...records.map(r=>fields.map(f=>[...r.children].find(n=>n.tagName===f)?.textContent||''))];return parseData(JSON.stringify(rows),{kind:'json',types:columnTypes});}
  const rows=parseData(text,{kind,separator,header:kind==='json'||header,types:columnTypes});return kind==='csv'&&!header?[Array.from({length:Math.max(...rows.map(r=>r.length))},(_,i)=>'Columna '+(i+1)),...rows]:rows;
 }
 function importRows(){return parseImportPayload(get('import-text'),get('import-kind'),get('separator'),checked('header'),Array(26).fill(get('import-type')));}
 async function fetchPublic(address){const url=new URL(address);if(url.protocol!=='https:'||url.username||url.password)throw Error('Usa una dirección HTTPS sin credenciales.');let res;try{res=await fetch(url.href,{signal:AbortSignal.timeout(15000),credentials:'omit'});}catch{throw Error('No se pudo leer la dirección. Comprueba la conexión y que el origen permita acceso desde el navegador (CORS).');}if(!res.ok)throw Error('El origen respondió HTTP '+res.status);if(Number(res.headers.get('content-length'))>2e6)throw Error('El contenido supera 2 MB.');const reader=res.body.getReader(),chunks=[];let length=0;while(true){const {value,done}=await reader.read();if(done)break;length+=value.byteLength;if(length>2e6){await reader.cancel();throw Error('El contenido supera 2 MB.');}chunks.push(value);}const data=new Uint8Array(length);let offset=0;for(const chunk of chunks){data.set(chunk,offset);offset+=chunk.length;}return {text:new TextDecoder('utf-8').decode(data),kind:/json/.test(res.headers.get('content-type')||'')?'json':/xml/.test(res.headers.get('content-type')||'')?'xml':'csv'};}
 async function refreshedQuery(q){const copy=structuredClone(q);if(q.source.type==='web'){const data=await fetchPublic(q.source.url);copy.source.rows=parseImportPayload(data.text,q.source.kind||data.kind,q.source.separator,q.source.header!==false,q.source.types||[]);}return copy;}
 async function refreshOne(id){const q=book().dataQueries?.find(q=>q.id===id);if(!q)throw Error('La consulta ya no existe.');const updated=await refreshedQuery(q);mutate(()=>{storeQuery(updated);loadQuery(book(),updated);});}

 async function importFile(){const file=await api.selectFile('.csv,.txt,.tsv,.json,.xml');if(!file)return;if(/\.xlsx$/i.test(file.name))throw Error('Para un libro de Excel utiliza Abrir XLSX.');if(file.size>2e6)throw Error('El archivo supera 2 MB.');const buffer=await file.arrayBuffer();importDraft={name:file.name.replace(/\.[^.]+$/,''),text:new TextDecoder('utf-8',{fatal:false}).decode(buffer),buffer,kind:/\.json$/i.test(file.name)?'json':/\.xml$/i.test(file.name)?'xml':'csv',separator:/\.tsv$/i.test(file.name)?'\t':';'};importPanel();}
 function queryPanel(q){mode='query';editingStep=null;qDraft=structuredClone(q);currentQuery=q.id;renderQuery();}
 function renderQuery(){const q=qDraft;let rows;try{const all={...book(),dataQueries:[...(book().dataQueries||[]).filter(v=>v.id!==q.id),q]};rows=queryResult(all,q);}catch(e){rows=null;}let inputRows=rows;if(editingStep!=null){try{const input={...q,steps:q.steps.slice(0,editingStep)};inputRows=queryResult({...book(),dataQueries:[...(book().dataQueries||[]).filter(v=>v.id!==q.id),input]},input);}catch{inputRows=null;}}const headers=inputRows?.[0]||[],cols=Object.fromEntries(headers.map((h,i)=>[i,h]));show('Editor de consultas',field('query-name','Nombre',q.name)+(q.needsReview?'<p>Las columnas de origen cambiaron. Revisa el rango y restablece los pasos antes de continuar.</p>'+btn('data-reset-query','Restablecer pasos'):'')+'<p>Origen: '+esc(q.source.type==='range'?book().sheets.find(s=>s.id===q.source.sheetId)?.name+'!'+q.source.range:q.source.label||q.source.type)+'</p><div class="sx-data-steps">'+(q.steps||[]).map((s,i)=>'<article><span>'+(i+1)+'. '+esc(s.type)+' · '+esc(headers[s.column]??'')+'</span><button data-dt-step-edit="'+i+'" aria-label="Editar paso">✎</button><button data-dt-step-remove="'+i+'" aria-label="Quitar paso">×</button></article>').join('')+'</div>'+choice('step-type','Agregar transformación',{trim:'Recortar espacios',clean:'Limpiar caracteres',type:'Cambiar tipo',filter:'Filtrar filas',sort:'Ordenar filas',unique:'Quitar duplicados',select:'Conservar columnas',replace:'Reemplazar texto',split:'Dividir columna',group:'Agrupar y agregar'},'trim')+choice('step-column','Columna',cols,0)+choice('step-target','Nuevo tipo',types,'number')+choice('step-op','Condición',opItems,'contains')+field('step-query','Valor','')+field('step-replace','Reemplazar por','')+choice('step-direction','Orden',{1:'Ascendente','-1':'Descendente'},1)+field('step-columns','Columnas: números desde 1 separados por ;','1')+field('step-separator','Separador',';')+choice('step-value','Columna de valores',cols,Math.min(1,headers.length-1))+choice('step-operation','Función',aggregateNames,'sum')+btn('data-add-step',editingStep==null?'Agregar paso':'Guardar cambios del paso')+btn('data-combine','Combinar / anexar consultas')+btn('data-save-query','Guardar consulta')+btn('data-load-query','Cerrar y cargar')+btn('data-load-new','Cargar en nueva hoja')+(rows?preview(rows):'<p class="sx-data-error">Un paso no es válido. Revísalo o elimínalo.</p>'));updateStep();}
